import fitz
import os
import re

# Redaction configurations
configs = {
    "paper1.pdf": {
        "authors": [
            "Yueqian Lin", "Zhengmian Hu", "Qinsi Wang", "Yudong Liu", 
            "Hengfan Zhang", "Jayakumar Subramanian", "Nikos Vlassis", 
            "Hai “Helen” Li", "Yiran Chen"
        ],
        "first_page_only": [
            "Duke University", "Durham, NC, USA", 
            "Adobe", "San Jose, CA, USA",
            "yueqian.lin@duke.edu", "zhengmianh@adobe.com",
            "Correspondence:", "♠", "♣"
        ]
    },
    "paper2.pdf": {
        "authors": [
            "Jiatong Shi", "Yueqian Lin", "Xinyi Bai", "Keyi Zhang", 
            "Yuning Wu", "Yuxun Tang", "Yifeng Yu", "Qin Jin", 
            "Shinji Watanabe"
        ],
        "first_page_only": [
            "Carnegie Mellon University", "Duke Kunshan University", "Cornell University",
            "Multimodal Art Projection Community", "Renmin University of China",
            "Georgia Institute of Technology", "jiatongs@cs.cmu.edu",
            "1,∗", "2,∗", "3,4", "5", "6", "⋆"
        ]
    },
    "paper3.pdf": {
        "authors": [
            "Yueqian Lin", "Yuzhe Fu", "Jingyang Zhang", "Yudong Liu", 
            "Jianyi Zhang", "Jingwei Sun", "Hai Li", "Yiran Chen"
        ],
        "first_page_only": [
            "Duke University", "Durham, USA",
            "Correspondence to:", "yl7"
        ]
    }
}

common_redactions = ["arXiv", "submitted to", "accepted by"]

def redact_pdf(filename, config):
    src_path = os.path.join("/root", filename)
    dst_path = os.path.join("/root/redacted", filename)

    print(f"Processing {filename}...")
    try:
        doc = fitz.open(src_path)

        # 1. Redact Authors (Everywhere)
        for author in config["authors"]:
            for page in doc:
                quads = page.search_for(author)
                if quads:
                    page.add_redact_annot(quads, fill=(0, 0, 0))

        # 2. Redact specific info (First Page Only)
        page0 = doc[0]
        for term in config["first_page_only"]:
            quads = page0.search_for(term)
            if quads:
                page0.add_redact_annot(quads, fill=(0, 0, 0))

        # 3. Common Redactions (Everywhere - looking for headers/footers mainly)
        # We can be broader here.
        for page in doc:
             # Search for arXiv patterns using regex if possible, but fitz search_for is text based.
             # We'll search for specific keywords.
             for term in common_redactions:
                 quads = page.search_for(term)
                 if quads:
                     page.add_redact_annot(quads, fill=(0, 0, 0))

        # Apply redactions
        for page in doc:
            page.apply_redactions()

        doc.save(dst_path)
        print(f"Saved redacted file to {dst_path}")

    except Exception as e:
        print(f"Failed to process {filename}: {e}")

if __name__ == "__main__":
    if not os.path.exists("/root/redacted"):
        os.makedirs("/root/redacted")

    for filename, config in configs.items():
        redact_pdf(filename, config)

